const message = $input.first().json;
const msg = message?.message;
if (!msg) return [{ json: { skip: true, chat_id: '', text: '', username: '', first_name: '', is_admin_command: false, is_group: false, is_media: false, message_id: 0 } }];

const chat_id = String(msg?.chat?.id || msg?.from?.id || '');
const chat_type = msg?.chat?.type || 'private';
const is_group = chat_type === 'group' || chat_type === 'supergroup';
const text = msg?.text || msg?.caption || '';
const username = msg?.from?.username || '';
const first_name = msg?.from?.first_name || 'Клієнт';
const message_id = msg?.message_id || 0;
const is_media = !text && !!(msg?.photo || msg?.document || msg?.video || msg?.voice || msg?.audio || msg?.sticker);

// Блокліст: повністю ігнорувати повідомлення від цих Telegram user id (спам)
const blocked_user_ids = ['1853688388']; // Viktor Kovalchuk @Wiktor_Kowalczuk — спам «Сицилія», 16.07.2026
if (blocked_user_ids.includes(String(msg?.from?.id || ''))) {
  return [{ json: { skip: true, chat_id, text, username, first_name, is_admin_command: false, is_group: true, is_media: false, message_id } }];
}

const admin_commands = ['/pause', '/resume', '/getchatid', '/setmanager', '/status', '/msg'];
const is_admin_command = admin_commands.some(cmd => text.startsWith(cmd));

if (is_group && !is_admin_command) {
  return [{ json: { skip: true, chat_id, text, username, first_name, is_admin_command: false, is_group: true, is_media: false, message_id } }];
}

// Debounce: store latest message_id per chat
const wd = $getWorkflowStaticData('global');
if (!wd.last_msg_id) wd.last_msg_id = {};
wd.last_msg_id[chat_id] = message_id;

if (is_media) {
  return [{ json: { chat_id, text: '[МЕДІАФАЙЛ]', username, first_name, is_admin_command: false, is_group, is_media: true, message_id } }];
}
if (!text) {
  return [{ json: { chat_id, text: '[Клієнт надіслав повідомлення]', username, first_name, is_admin_command: false, is_group, is_media: false, message_id } }];
}
return [{ json: { chat_id, text, username, first_name, is_admin_command, is_group, is_media: false, message_id } }];

const { chat_id, text } = $input.first().json;
const wd = $getWorkflowStaticData('global');
if (!wd.paused_chats) wd.paused_chats = [];
if (!wd.manager_ids) wd.manager_ids = [];
let response = '', send_to = chat_id;
if (text === '/getchatid') {
  response = 'Ваш chat ID: ' + chat_id;
} else if (text === '/setmanager') {
  if (!wd.manager_ids.includes(chat_id)) wd.manager_ids.push(chat_id);
  response = 'Зареєстровано як менеджера. Chat ID: ' + chat_id + '\n\nКоманди:\n/pause CHATID\n/resume CHATID\n/msg CHATID Текст\n/status\n/getchatid';
} else if (text.startsWith('/pause')) {
  const t = text.split(' ')[1] || '';
  if (t && !wd.paused_chats.includes(t)) wd.paused_chats.push(t);
  response = t ? 'Бот призупинено для ' + t : 'Формат: /pause CHATID';
} else if (text.startsWith('/resume')) {
  const t = text.split(' ')[1] || '';
  if (t) { wd.paused_chats = wd.paused_chats.filter(id => id !== t); response = 'Бота відновлено для ' + t; }
  else response = 'Формат: /resume CHATID';
} else if (text.startsWith('/msg')) {
  const parts = text.split(' ');
  const t = parts[1] || '', msg = parts.slice(2).join(' ');
  if (t && msg) { send_to = t; response = msg; }
  else response = 'Формат: /msg CHATID Текст';
} else if (text === '/status') {
  response = 'Менеджери:\n' + (wd.manager_ids.join('\n') || 'немає') + '\n\nПризупинені:\n' + (wd.paused_chats.join('\n') || 'немає');
}
return [{ json: { chat_id: send_to, response_text: response } }];

const { chat_id } = $input.first().json;
const wd = $getWorkflowStaticData('global');
const is_paused = (wd.paused_chats || []).includes(chat_id);
return [{ json: { ...$input.first().json, is_paused } }];

const output = $('AI Agent').item.json.output || '';
const chat_id = $('Code: Prepare').item.json.chat_id;
const username = $('Code: Prepare').item.json.username ? '@' + $('Code: Prepare').item.json.username : '';
const first_name = $('Code: Prepare').item.json.first_name || 'Клієнт';
const summaryMatch = output.match(/Маршрут:[\s\S]*/);
const summary = summaryMatch ? summaryMatch[0] : output;
const now = new Date().toLocaleString('uk-UA', { timeZone: 'Europe/Kiev' });
return [{ json: {
  subject: 'Новий запит на перевезення — ' + first_name + (username ? ' ' + username : ''),
  body: 'Новий запит на перевезення з Telegram-бота UNITEX.\n\nКлієнт: ' + first_name + (username ? ' ' + username : '') + '\nChat ID: ' + chat_id + '\n\nДЕТАЛІ ВАНТАЖУ:\n\n' + summary + '\n\n---\nДата: ' + now
}}];

const { chat_id, message_id } = $('Code: Prepare').item.json;
const wd = $getWorkflowStaticData('global');
const latest_id = (wd.last_msg_id || {})[chat_id] || message_id;
const is_latest = latest_id === message_id;
return [{ json: { ...$input.first().json, is_latest } }];

